<?php $vals=[]; foreach($settings as $s) $vals[$s['key']]=$s['value']; $defaults=['scan_profile'=>config('guard.scan_profile'),'timer_scan_profile'=>config('guard.timer_scan_profile'),'scan_roots'=>implode(',',config('guard.scan_roots')),'quarantine_path'=>config('guard.quarantine_path'),'scan_interval_minutes'=>config('guard.scan_interval_minutes'),'web_actions_enabled'=>config('guard.web_actions_enabled')?'true':'false','openai_api_key'=>config('guard.openai_api_key'),'openai_enabled'=>config('guard.openai_enabled')?'true':'false','max_file_read_bytes'=>config('guard.max_file_read_bytes'),'backup_integration_enabled'=>config('guard.backup_integration_enabled')?'true':'false','backup_provider'=>config('guard.backup_provider'),'ispmanager_detected'=>config('guard.ispmanager_detected')?'true':'false','backup_root'=>config('guard.backup_root'),'backup_browser_enabled'=>config('guard.backup_browser_enabled')?'true':'false','backup_restore_enabled'=>config('guard.backup_restore_enabled')?'true':'false','restore_current_file_to_quarantine'=>config('guard.restore_current_file_to_quarantine')?'true':'false']; ob_start(); ?>
<h1>Settings</h1><p class="muted">Settings are stored in DB for the MVP; deployment environment variables remain authoritative where config reads env directly.</p>
<form method="post" class="card"><h2>Scanning</h2><?php foreach(array_slice($defaults,0,8,true) as $k=>$v): ?><label><?= e($k) ?><br><input class="input" style="width:100%" name="settings[<?= e($k) ?>]" value="<?= e($vals[$k] ?? $v) ?>"></label><br><br><?php endforeach ?><h2>Backups</h2><p class="muted">Enable ISPmanager/custom backup browser separately from restore. Web restore is disabled by default; when disabled the UI shows the exact CLI command.</p><?php foreach(array_slice($defaults,8,null,true) as $k=>$v): ?><label><?= e($k) ?><br><?php if($k==='backup_provider'): ?><select class="input" name="settings[<?= e($k) ?>]"><?php foreach(['ispmanager'=>'ISPmanager','custom'=>'Custom backup folder','disabled'=>'Disabled'] as $val=>$label): ?><option value="<?= e($val) ?>" <?= (($vals[$k] ?? $v)===$val)?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select><?php else: ?><input class="input" style="width:100%" name="settings[<?= e($k) ?>]" value="<?= e($vals[$k] ?? $v) ?>"><?php endif ?></label><br><br><?php endforeach ?><button class="btn">Save</button></form>
<?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
